import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)

DATABASE = '/app/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL,
        action TEXT,
        details TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, password_hash, role, api_key) VALUES ('admin', 'admin@corp.internal', 'pbkdf2:sha256:260000$salt$hash', 'admin', 'ak_prod_9f8e7d6c5b4a')")
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    if not key:
        return False
    db = get_db()
    row = db.execute("SELECT id FROM users WHERE api_key = ?", (key,)).fetchone()
    return row is not None

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401

    username = request.args.get('username', '')
    role_filter = request.args.get('role', '')

    # Build query with filters
    query = "SELECT id, username, email, role FROM users WHERE 1=1"

    if username:
        query += f" AND username LIKE '%{username}%'"

    if role_filter:
        query += f" AND role = '{role_filter}'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        # Log the search action
        db.execute("INSERT INTO audit_log (timestamp, action, details) VALUES (?, ?, ?)",
                   (time.time(), 'user_search', f'query_params: username={username}, role={role_filter}'))
        db.commit()
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    row = db.execute("SELECT id, username, email, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
